let lrgrep_execute_error_messages 
  (__clause, (__registers : Parser.MenhirInterpreter.element CamlinternalLrgrep_runtime.register_values))
  ((token : Parser.MenhirInterpreter.token), _startloc_token_, _endloc_token_)
  : _ option = match __clause, token with
  | 0, (ELSE) ->
    let e, _startpos_e_, _endpos_e_, _positions_e_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | N N_fun_expr -> (x : Parsetree.expression)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = e in
    (
# 35 "parsing/parse_errors.lrgrep"
            
    match e with
    | {pexp_desc = Pexp_ifthenelse(_, _, None); _} -> (
      Some ("The semicolon " ^ line_and_char _startpos_e_
            ^ " terminates the `if ... then ...` expression. \
            Remove it to add an else branch.")
      )
    | _ -> None
  
# 63 "parsing/parse_errors.ml"
    )
  | (0), _ -> None
  | 1, _ ->
    let typs, _startpos_typs_, _endpos_typs_, _positions_typs_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | N N_reversed_separated_nontrivial_llist_COMMA_core_type_ -> (x : Parsetree.core_type list)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = typs in
    let rp, _startpos_rp_, _endpos_rp_, _positions_rp_ = match __registers.(1) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | T T_RPAREN -> (x : unit)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = rp in
    (
# 48 "parsing/parse_errors.lrgrep"
            
    match List.rev typs with
    | [] | [_] -> None
    | typs -> Some Ast_helper.(
      Printf.sprintf
        "The preceding type ending %s is incomplete.\n\
         It's missing a type constructor after the parameters, for instance: %s.\n\
         If you meant to write a tuple, use '*': %s."
        (line_and_char _endpos_rp_)
        (Format.asprintf "%a" Pprintast.core_type
          (Typ.constr (Location.mknoloc (Longident.Lident "t")) typs))
        (Format.asprintf "%a" Pprintast.core_type
          (Typ.tuple (List.map (fun t -> (None,t)) typs)))
    )
  
# 106 "parsing/parse_errors.ml"
    )
  | 2, (EQUAL) ->
    Some (
# 65 "parsing/parse_errors.lrgrep"
    "Expecting ':' to declare the type of a record field, not '='" 
# 112 "parsing/parse_errors.ml"
    )
  | (2), _ -> None
  | 3, _ ->
    let semi, _startpos_semi_, _endpos_semi_, _positions_semi_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | T T_SEMI -> (x : unit)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = semi in
    Some (
# 70 "parsing/parse_errors.lrgrep"
    "Expecting 'in' to complete local-let binding. Hint: this might be due to the semicolon " ^ line_and_char _startpos_semi_ 
# 130 "parsing/parse_errors.ml"
    )
  | 4, _ ->
    let loc, _startpos_loc_, _endpos_loc_, _positions_loc_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (_, _, startp, endp)as x) ->
        (x, startp, endp, (startp, endp))
    in
    let _ = loc in
    Some (
# 73 "parsing/parse_errors.lrgrep"
    "Expecting 'in' after let binding(s) in an expression. \n\
     This might be due to the unterminated expression at " ^
     line_and_char _endpos_loc_ 
# 145 "parsing/parse_errors.ml"
    )
  | 5, (IN) ->
    let item, _startpos_item_, _endpos_item_, _positions_item_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | N N_structure_item -> (x : Parsetree.structure_item)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = item in
    Some (
# 78 "parsing/parse_errors.lrgrep"
    "A 'let ... in' expression is not allowed immediately after a definition. \n\
    This can be solved by inserting ';;' or 'let () = ' after " ^ line_and_char _endpos_item_ 
# 163 "parsing/parse_errors.ml"
    )
  | (5), _ -> None
  | 6, _ ->
    let lp, _startpos_lp_, _endpos_lp_, _positions_lp_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | T T_LPAREN -> (x : unit)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = lp in
    Some (
# 83 "parsing/parse_errors.lrgrep"
    "Unclosed parenthesis at " ^ line_and_char _startpos_lp_ 
# 181 "parsing/parse_errors.ml"
    )
  | 7, _ ->
    let _startpos_pos_ = match __registers.(0) with
      | Empty -> assert false
      | Location (p, _) | Value (Parser.MenhirInterpreter.Element (_, _, p, _)) -> p
    in
    let _endpos_pos_ = match __registers.(1) with
      | Empty -> assert false
      | Location (_, p) | Value (Parser.MenhirInterpreter.Element (_, _, _, p)) -> p
    in
    Some (
# 88 "parsing/parse_errors.lrgrep"
    "Expecting `in' to continue let-binding at " ^ line_and_char _startpos_pos_ 
# 195 "parsing/parse_errors.ml"
    )
  | 8, _ ->
    (
# 94 "parsing/parse_errors.lrgrep"
             match Lexer.as_keyword token with
    | None -> None
    | Some kw ->
      Some ("`" ^ kw ^ "' is a keyword and cannot appear in this context (try " ^ kw ^ "_)")
  
# 205 "parsing/parse_errors.ml"
    )
  | 9, (MODULE) ->
    Some (
# 106 "parsing/parse_errors.lrgrep"
     "`module' keyword cannot appear in an expression, \
       use `(module M)' to pack a first class-module \
       or `let module M = ... in ...' to define a local module"
  
# 214 "parsing/parse_errors.ml"
    )
  | (9), _ -> None
  | 10, (MINUSGREATER) ->
    Some (
# 114 "parsing/parse_errors.lrgrep"
    "Issue #11445: in constructor arguments, \
     arrow types should be wrapped between parentheses"
  
# 223 "parsing/parse_errors.ml"
    )
  | (10), _ -> None
  | 11, (UNDERSCORE|UIDENT _|LPAREN|LIDENT _) ->
    let outer, _startpos_outer_, _endpos_outer_, _positions_outer_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | N N_constr_longident -> (x : Longident.t)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = outer in
    let inner, _startpos_inner_, _endpos_inner_, _positions_inner_ = match __registers.(1) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | N N_constr_longident -> (x : Longident.t)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = inner in
    Some (
# 121 "parsing/parse_errors.lrgrep"
    report_currified_constructor ~outer inner token 
# 252 "parsing/parse_errors.ml"
    )
  | (11), _ -> None
  | 12, (UIDENT _|TRUE|STRING _|QUOTED_STRING_EXPR _|PREFIXOP _|OBJECT|NEW|METAOCAML_ESCAPE|METAOCAML_BRACKET_OPEN|LPAREN|LIDENT _|LBRACKETPERCENT|LBRACKETBAR|LBRACKET|LBRACELESS|LBRACE|INT _|FLOAT _|FALSE|CHAR _|BEGIN|BANG|BACKQUOTE) ->
    Some (
# 125 "parsing/parse_errors.lrgrep"
    (* Expliquer le raisonnement *)
    (* Plusieurs niveaux d'explications ? *)
    (* Message court identifiant la situation *)
    (* Hint pour détailler. (Rappel de la syntaxe) *)
    "Application of n-ary constructors cannot be currified, \
     arguments should be wrapped between parentheses and comma separated" 
# 264 "parsing/parse_errors.ml"
    )
  | (12), _ -> None
  | 13, (UNDERSCORE|UIDENT _|LPAREN|LIDENT _) ->
    let inner, _startpos_inner_, _endpos_inner_, _positions_inner_ = match __registers.(0) with 
      | Empty -> assert false
      | Location _ -> assert false
      | Value (Parser.MenhirInterpreter.Element (st, x, startp, endp)) ->
        let x = match Parser.MenhirInterpreter.incoming_symbol st with
          | N N_constr_longident -> (x : Longident.t)
          | _ -> assert false
        in
        (x, startp, endp, (startp, endp))
    in
    let _ = inner in
    Some (
# 135 "parsing/parse_errors.lrgrep"
    report_currified_constructor inner token 
# 282 "parsing/parse_errors.ml"
    )
  | (13), _ -> None
  | 14, (LBRACKETATAT) ->
    Some (
# 138 "parsing/parse_errors.lrgrep"
    "[@@ ...] attribute should be placed after a type (note that it attaches to the item, not to the type)" 
# 289 "parsing/parse_errors.ml"
    )
  | (14), _ -> None
  | 15, (LBRACKETAT) ->
    Some (
# 141 "parsing/parse_errors.lrgrep"
    "[@ ...] attribute should be placed after a type" 
# 296 "parsing/parse_errors.ml"
    )
  | (15), _ -> None
  | 16, _ ->
